function formatEmailHtml(text) {
    return text
        // Nettoyage des titres Markdown (### Titre -> Gras aéré)
        .replace(/^#+\s+(.*)$/gm, '<div style="margin-top: 15px; margin-bottom: 5px;"><b>$1</b></div>')

        // Gras standard
        .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')

        // Liens
        .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #007BFF; text-decoration: underline;">$1</a>')

        // Listes à puces (groupées sans trop d'espace entre elles)
        .replace(/^\s*[\-\*]\s+(.*)$/gm, '<div style="margin-left: 15px; margin-bottom: 2px;">• $1</div>')

        // Gestion des paragraphes (Double saut de ligne -> Bloc avec marge)
        .split(/\n\n+/).map(para => {
            if (para.includes('<div')) return para; // Ne pas toucher si c'est déjà formaté
            return `<div style="margin-bottom: 12px;">${para.replace(/\n/g, "<br>")}</div>`;
        }).join("");
}

subject = subject.replace(/[#\*]/g, ""); // Nettoyer le sujet
