// 1. RÉCUPÉRATION DES TRANSCRIPTIONS
const node1 = $('Transcribe Part 1').item.json;
const text1 = node1.candidates?.[0]?.content?.parts?.[0]?.text || "";

let text2 = "";
try {
    const node2 = $('Transcribe Part 2').item.json;
    text2 = node2.candidates?.[0]?.content?.parts?.[0]?.text || "";
    if (text2) {
        text2 = "\n\n[--- SUITE DE L'APPEL (PARTIE 2) ---]\n\n" + text2;
    }
} catch (e) {
    // Ignore si partie 2 n'existe pas
}

// 2. RÉCUPÉRATION DU COMMENTAIRE DU FORMULAIRE
const formData = $('On form submission').item.json;
const salesComment = formData.sales_comment || "";

// 3. CONSTRUCTION DU TEXTE ENRICHI
let enrichedText = "";

// Ajouter le commentaire du vendeur EN PREMIER (contexte important)
if (salesComment && salesComment.trim() !== "") {
    enrichedText += "=== NOTES DU VENDEUR (AVANT L'APPEL) ===\n";
    enrichedText += salesComment.trim();
    enrichedText += "\n\n=== TRANSCRIPTION DE L'APPEL ===\n\n";
}

// Ajouter les transcriptions
enrichedText += text1 + text2;

// 4. RETOUR STRUCTURÉ
return {
    json: {
        text: enrichedText,
        transcription_brute: text1 + text2,
        sales_comment: salesComment,
        metadata: {
            has_part2: text2 !== "",
            has_sales_comment: salesComment.trim() !== "",
            total_length: enrichedText.length
        }
    }
};

// Récupérer les données de l'input (résultat de la requête HTTP Pipedrive)
// Pipedrive renvoie souvent les données dans une propriété "data"
const inputData = $input.first().json.data || $input.first().json;

const now = new Date();
const futureCohorts = [];

// Mapping des mois français pour la conversion
const months = {
  'janvier': 0, 'février': 1, 'mars': 2, 'avril': 3, 'mai': 4, 'juin': 5,
  'juillet': 6, 'août': 7, 'septembre': 8, 'octobre': 9, 'novembre': 10, 'décembre': 11
};

// Filtrer et traiter les stages
for (const stage of inputData) {
  // Vérification de sécurité si le nom existe
  if (stage.name && stage.name.startsWith('Cohorte')) {

    const title = stage.name.toLowerCase();

    // Regex pour capturer la date entre parenthèses ou dans le titre
    // Ex: "Cohorte 55 (12 février)" -> capture "12" et "février"
    const match = title.match(/(\d{1,2})\s+(janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre)/);

    if (match) {
      const day = parseInt(match[1]);
      const monthStr = match[2];
      const month = months[monthStr];

      // Gestion de l'année : Si on est en Décembre et la cohorte est en Janvier, c'est l'année prochaine
      let year = now.getFullYear();
      if (month < now.getMonth() && (now.getMonth() > 9)) { 
          year += 1; 
      }

      const cohortDate = new Date(year, month, day);

      // On ne garde que les dates futures (ou aujourd'hui)
      // On enlève 1 jour à "now" pour garder les cohortes du jour même
      const yesterday = new Date(now);
      yesterday.setDate(yesterday.getDate() - 1);

      if (cohortDate >= yesterday) {
        // Formatage propre pour l'email (ex: "Jeudi 12 février")
        const options = { weekday: 'long', day: 'numeric', month: 'long' };
        const formattedDate = cohortDate.toLocaleDateString('fr-FR', options);
        const finalString = formattedDate.charAt(0).toUpperCase() + formattedDate.slice(1);

        futureCohorts.push({
          stage_id: stage.id,
          nom_pipedrive: stage.name,
          date_iso: cohortDate.toISOString(), // Pour le tri informatique
          date_email: finalString, // Pour l'affichage dans le mail (ex: "Jeudi 12 février")
          jour_semaine: finalString.split(' ')[0] // ex: "Jeudi"
        });
      }
    }
  }
}

// Tri des cohortes par date (de la plus proche à la plus lointaine)
futureCohorts.sort((a, b) => new Date(a.date_iso) - new Date(b.date_iso));

return [{
  json: {
    cohortes_disponibles: futureCohorts
  }
}];

// 1. Récupération des données
const scoring = $('Mettre en variable le scoring output').first().json;
const cohortes = $('Cohortes ouvertes').first().json.cohortes_disponibles;
const currentDeal = $('Prospect opty retrieval').first().json.data[0];
const profileData = $('Profile Formatage pour PipeDrive').first().json;

// 2. Extraction de la probabilité (votre chemin spécifique)
const probability = scoring.analyse_scores?.probabilite_closing_immediat || scoring.probabilite_closing_immediat || 0;

// 3. Logique de déplacement dynamique du Stage
let targetStageId = currentDeal.stage_id;
const scenariosAvecDate = ['CAS_1_PREINSCRIT', 'CAS_2_REFLEXION_DATE_FIXEE'];

if (scenariosAvecDate.includes(scoring.scenario_logistique) && scoring.date_preferee) {
    const prefDate = scoring.date_preferee.split('T')[0];
    const match = cohortes.find(c => c.date_iso.startsWith(prefDate));
    if (match) {
        targetStageId = match.stage_id;
    }
}

// 4. Retour des données consolidées
return {
    deal_id: currentDeal.id,
    stage_id: targetStageId,
    probability: probability,
    ...profileData.custom_fields // Injecte automatiquement tous les champs personnalisés
};

const fullPath = $json.path || ""; 
const parts = fullPath.split(/[\\/]/);

// Regex pour capturer DATE (YYYY-MM-DD) et HEURE (HH.MM.SS)
const regex = /(\d{4}-\d{2}-\d{2})\s+(\d{2}\.\d{2}\.\d{2})\s+(.*?)\s+et\s+Djamel/;

// On cherche le segment du chemin qui correspond au pattern
const folderName = parts.find(p => p.match(regex)) || "Dossier inconnu";
const match = folderName.match(regex);

// Formatage de l'heure (remplacer les points par des deux-points pour la lisibilité)
let formattedTime = "Inconnue";
if (match && match[2]) {
    formattedTime = match[2].replace(/\./g, ":"); // Transforme 18.00.00 en 18:00:00
}

return {
  date: match ? match[1] : "Inconnue",
  time: formattedTime,
  prospectName: match ? match[3].trim() : "Inconnu",
  folderName: folderName,
  fullPath: fullPath
};

